new:
let C := compose producerComponent (consumerComponent other) (scalarBoundary other)
  let altered := { C.contract with
    collectors := C.contract.collectors.map fun row =>
      (row.1, row.2.filter (fun cap => cap != 204)) }
  let writers := C.fragment.writers.filter (fun w => w.capability != 204)
  runChecked altered ⟨writers⟩ (fun _ => none)
